using System.Globalization;
using System.Text;
using Dapper;
using InovaGed.Application.Common.Database;
using InovaGed.Application.ContractMeasurement;

namespace InovaGed.Infrastructure.ContractMeasurement;

public sealed class ContractMeasurementService(IDbConnectionFactory factory) : IContractMeasurementDashboardService, IContractServiceCatalogService, IContractProductivityService, IContractMeasurementPeriodService, IContractGlosaService, IContractMeasurementReportService
{
    public async Task<ContractMeasurementDashboard> GetDashboardAsync(Guid t,CancellationToken ct){await using var db=await factory.OpenAsync(ct);var r=await db.QuerySingleAsync<DashboardDbRow>(new CommandDefinition(@"select coalesce((select period_code from ged.contract_measurement_period where tenant_id=@t and reg_status='A' order by reference_year desc,reference_month desc limit 1),'Sem período') current_period,coalesce((select gross_amount from ged.contract_measurement_period where tenant_id=@t and reg_status='A' order by reference_year desc,reference_month desc limit 1),0) gross_amount,coalesce((select glosa_amount from ged.contract_measurement_period where tenant_id=@t and reg_status='A' order by reference_year desc,reference_month desc limit 1),0) glosa_amount,coalesce((select net_amount from ged.contract_measurement_period where tenant_id=@t and reg_status='A' order by reference_year desc,reference_month desc limit 1),0) net_amount,(select count(*) from ged.contract_productivity_entry where tenant_id=@t and status='DRAFT' and reg_status='A') pending_entries,(select count(*) from ged.contract_measurement_item where tenant_id=@t and reg_status='A') measured_items,(select count(*) from ged.contract_measurement_period where tenant_id=@t and status='SUBMITTED' and reg_status='A') pending_acceptances",new{t},cancellationToken:ct));return new(r.CurrentPeriod,r.GrossAmount,r.GlosaAmount,r.NetAmount,r.PendingEntries,r.MeasuredItems,r.PendingAcceptances,0);}
    public async Task<IReadOnlyList<ContractServiceCatalogItem>> ListAsync(Guid t,CancellationToken ct){await using var db=await factory.OpenAsync(ct);var rows=await db.QueryAsync<ServiceDbRow>(new CommandDefinition("select id,service_code,description,nature,unit_name,unit_value,default_active active from ged.contract_service_catalog where reg_status='A' and (tenant_id=@t or tenant_id is null) order by display_order,description",new{t},cancellationToken:ct));return rows.Select(x=>new ContractServiceCatalogItem(x.Id,x.ServiceCode,x.Description,x.Nature,x.UnitName,x.UnitValue,x.Active)).ToList();}
    public async Task<IReadOnlyList<ContractProductivityItem>> ListAsync(ContractProductivityFilter f,CancellationToken ct){await using var db=await factory.OpenAsync(ct);var rows=await db.QueryAsync<ProductivityDbRow>(new CommandDefinition(@"select e.id,e.service_id,s.description service,e.source_type,e.quantity,e.unit_value,e.total_value,e.performed_by_name,e.performed_at,e.status from ged.contract_productivity_entry e join ged.contract_service_catalog s on s.id=e.service_id where e.tenant_id=@TenantId and e.reg_status='A' and (@Month is null or extract(month from e.performed_at)=@Month) and (@Year is null or extract(year from e.performed_at)=@Year) and (@ServiceId is null or e.service_id=@ServiceId) and (coalesce(@User,'')='' or e.performed_by_name ilike '%'||@User||'%') and (coalesce(@Source,'')='' or e.source_type=@Source) and (coalesce(@Status,'')='' or e.status=@Status) and (coalesce(@Search,'')='' or s.description ilike '%'||@Search||'%' or coalesce(e.notes,'') ilike '%'||@Search||'%') order by e.performed_at desc",f,cancellationToken:ct));return rows.Select(x=>new ContractProductivityItem(x.Id,x.ServiceId,x.Service,x.SourceType,x.Quantity,x.UnitValue,x.TotalValue,x.PerformedByName,Offset(x.PerformedAt),x.Status)).ToList();}
    public async Task<Guid> CreateAsync(ContractProductivityCreateCommand c,CancellationToken ct){if(c.Quantity<=0||c.UnitValue<0)throw new ArgumentException("Quantidade deve ser positiva e valor unitário não pode ser negativo.");await using var db=await factory.OpenAsync(ct);if(c.DocumentId.HasValue&&!await Belongs(db,"ged.document","id",c.DocumentId.Value,c.TenantId,ct))throw new InvalidOperationException("Documento não pertence ao tenant.");if(c.BoxId.HasValue&&!await Belongs(db,"ged.archive_box","id",c.BoxId.Value,c.TenantId,ct))throw new InvalidOperationException("Caixa não pertence ao tenant.");var id=Guid.NewGuid();var n=await db.ExecuteAsync(new CommandDefinition(@"insert into ged.contract_productivity_entry(id,tenant_id,service_id,source_type,source_id,document_id,box_id,quantity,unit_value,total_value,performed_by,performed_by_name,performed_at,notes,evidence_required) select @id,@TenantId,@ServiceId,@SourceType,@SourceId,@DocumentId,@BoxId,@Quantity,@UnitValue,@total,@UserId,@UserName,@PerformedAt,@Notes,@EvidenceRequired from ged.contract_service_catalog where id=@ServiceId and reg_status='A' and (tenant_id=@TenantId or tenant_id is null)",new{id,c.TenantId,c.ServiceId,c.SourceType,c.SourceId,c.DocumentId,c.BoxId,c.Quantity,c.UnitValue,total=c.Quantity*c.UnitValue,c.UserId,c.UserName,c.PerformedAt,c.Notes,c.EvidenceRequired},cancellationToken:ct));if(n==0)throw new InvalidOperationException("Serviço indisponível para o tenant.");return id;}
    public async Task<IReadOnlyList<ContractMeasurementPeriodItem>> ListAsync(Guid t,CancellationToken ct){await using var db=await factory.OpenAsync(ct);var rows=await db.QueryAsync<PeriodDbRow>(new CommandDefinition("select id,period_code,reference_month,reference_year,status,gross_amount,glosa_amount,net_amount,opened_at,closed_at from ged.contract_measurement_period where tenant_id=@t and reg_status='A' order by reference_year desc,reference_month desc",new{t},cancellationToken:ct));return rows.Select(Period).ToList();}
    public async Task<ContractMeasurementPeriodDetails?> GetAsync(Guid t,Guid p,CancellationToken ct){await using var db=await factory.OpenAsync(ct);var row=await db.QuerySingleOrDefaultAsync<PeriodDbRow>(new CommandDefinition("select id,period_code,reference_month,reference_year,status,gross_amount,glosa_amount,net_amount,opened_at,closed_at from ged.contract_measurement_period where tenant_id=@t and id=@p and reg_status='A'",new{t,p},cancellationToken:ct));if(row is null)return null;var items=(await db.QueryAsync<ItemDbRow>(new CommandDefinition("select id,service_id,description,nature,unit_value,quantity,gross_amount,glosa_amount,net_amount,status from ged.contract_measurement_item where tenant_id=@t and period_id=@p and reg_status='A' order by description",new{t,p},cancellationToken:ct))).Select(Item).ToList();var ev=(await db.QueryAsync<EvidenceDbRow>(new CommandDefinition("select id,item_id,source_type,title,description,evidence_hash,registered_by_name,registered_at from ged.contract_measurement_evidence where tenant_id=@t and period_id=@p and reg_status='A' order by registered_at desc",new{t,p},cancellationToken:ct))).Select(Evidence).ToList();var gl=(await db.QueryAsync<GlosaDbRow>(new CommandDefinition("select id,period_id,item_id,glosa_number,reason,amount,status,opened_at,resolved_at from ged.contract_glosa where tenant_id=@t and period_id=@p and reg_status='A' order by opened_at desc",new{t,p},cancellationToken:ct))).Select(Glosa).ToList();var events=(await db.QueryAsync<EventDbRow>(new CommandDefinition("select event_type,title,description,performed_by_name,occurred_at from ged.contract_acceptance_event where tenant_id=@t and period_id=@p and reg_status='A' order by occurred_at desc",new{t,p},cancellationToken:ct))).Select(x=>new ContractAcceptanceEvent(x.EventType,x.Title,x.Description,x.PerformedByName,Offset(x.OccurredAt))).ToList();return new(Period(row),items,ev,gl,events);}
    public async Task<Guid>CreateAsync(ContractMeasurementPeriodCreateCommand c,CancellationToken ct){if(c.ReferenceMonth is <1 or >12||c.ReferenceYear<2000)throw new ArgumentException("Competência inválida.");await using var db=await factory.OpenAsync(ct);var id=Guid.NewGuid();var code=$"{c.ReferenceYear:D4}-{c.ReferenceMonth:D2}";try{await db.ExecuteAsync(new CommandDefinition(@"insert into ged.contract_measurement_period(id,tenant_id,period_code,reference_month,reference_year,opened_by,notes) values(@id,@TenantId,@code,@ReferenceMonth,@ReferenceYear,@UserId,@Notes);insert into ged.contract_acceptance_event(tenant_id,period_id,event_type,title,performed_by) values(@TenantId,@id,'CONTRACT_MEASUREMENT_PERIOD_CREATED','Período de medição criado',@UserId)",new{id,c.TenantId,code,c.ReferenceMonth,c.ReferenceYear,c.UserId,c.Notes},cancellationToken:ct));return id;}catch(Exception ex)when(ex.Message.Contains("ux_contract_measurement_period",StringComparison.OrdinalIgnoreCase)){throw new InvalidOperationException("Já existe período para esta competência.");}}
    public async Task GenerateItemsAsync(Guid t,Guid p,Guid u,CancellationToken ct){await using var db=await factory.OpenAsync(ct);await using var tx=await db.BeginTransactionAsync(ct);var state=await db.ExecuteScalarAsync<string?>(new CommandDefinition("select status from ged.contract_measurement_period where tenant_id=@t and id=@p and reg_status='A' for update",new{t,p},tx,cancellationToken:ct));Mutable(state);await db.ExecuteAsync(new CommandDefinition(@"delete from ged.contract_measurement_item where tenant_id=@t and period_id=@p;insert into ged.contract_measurement_item(tenant_id,period_id,service_id,description,nature,unit_value,quantity,gross_amount,net_amount) select e.tenant_id,@p,e.service_id,s.description,s.nature,e.unit_value,sum(e.quantity),sum(e.total_value),sum(e.total_value) from ged.contract_productivity_entry e join ged.contract_service_catalog s on s.id=e.service_id join ged.contract_measurement_period mp on mp.id=@p and mp.tenant_id=e.tenant_id where e.tenant_id=@t and e.reg_status='A' and extract(month from e.performed_at)=mp.reference_month and extract(year from e.performed_at)=mp.reference_year group by e.tenant_id,e.service_id,s.description,s.nature,e.unit_value;update ged.contract_measurement_period mp set status='GENERATED',gross_amount=x.gross,glosa_amount=0,net_amount=x.gross from(select coalesce(sum(gross_amount),0) gross from ged.contract_measurement_item where tenant_id=@t and period_id=@p)x where mp.tenant_id=@t and mp.id=@p;insert into ged.contract_acceptance_event(tenant_id,period_id,event_type,title,performed_by) values(@t,@p,'CONTRACT_MEASUREMENT_ITEMS_GENERATED','Itens agrupados por serviço',@u)",new{t,p,u},tx,cancellationToken:ct));await tx.CommitAsync(ct);}
    public Task SubmitAsync(Guid t,Guid p,Guid u,CancellationToken ct)=>Transition(t,p,u,"SUBMITTED","CONTRACT_MEASUREMENT_SUBMITTED","Medição submetida ao aceite",null,"status in('GENERATED','REJECTED') and exists(select 1 from ged.contract_measurement_item where tenant_id=@t and period_id=@p and reg_status='A')",ct);
    public async Task ApproveAsync(Guid t,Guid p,Guid u,string?notes,CancellationToken ct){await using var db=await factory.OpenAsync(ct);var open=await db.ExecuteScalarAsync<int>(new CommandDefinition("select count(*) from ged.contract_glosa where tenant_id=@t and period_id=@p and status='OPEN' and reg_status='A'",new{t,p},cancellationToken:ct));if(open>0&&string.IsNullOrWhiteSpace(notes))throw new InvalidOperationException("Justifique o aceite com glosas abertas.");await Transition(t,p,u,"APPROVED","CONTRACT_MEASUREMENT_APPROVED","Aceite do fiscal aprovado",notes,"status='SUBMITTED'",ct);}
    public Task RejectAsync(Guid t,Guid p,Guid u,string reason,CancellationToken ct){if(string.IsNullOrWhiteSpace(reason))throw new ArgumentException("Motivo da rejeição é obrigatório.");return Transition(t,p,u,"REJECTED","CONTRACT_MEASUREMENT_REJECTED","Aceite rejeitado",reason,"status='SUBMITTED'",ct);}
    public Task CloseAsync(Guid t,Guid p,Guid u,CancellationToken ct)=>Transition(t,p,u,"CLOSED","CONTRACT_MEASUREMENT_CLOSED","Período encerrado",null,"status='APPROVED'",ct);
    public async Task<Guid> RegisterEvidenceAsync(Guid t,Guid p,Guid?itemId,string?sourceType,Guid?sourceId,string title,string?description,string?hash,Guid u,string?name,CancellationToken ct){if(string.IsNullOrWhiteSpace(title))throw new ArgumentException("Título obrigatório.");await using var db=await factory.OpenAsync(ct);var id=Guid.NewGuid();var n=await db.ExecuteAsync(new CommandDefinition(@"insert into ged.contract_measurement_evidence(id,tenant_id,period_id,item_id,source_type,source_id,title,description,evidence_hash,registered_by,registered_by_name) select @id,@t,@p,@itemId,@sourceType,@sourceId,@title,@description,@hash,@u,@name from ged.contract_measurement_period where tenant_id=@t and id=@p and status not in('APPROVED','CLOSED');insert into ged.contract_acceptance_event(tenant_id,period_id,event_type,title,performed_by,performed_by_name) select @t,@p,'CONTRACT_EVIDENCE_REGISTERED','Evidência registrada',@u,@name where exists(select 1 from ged.contract_measurement_evidence where id=@id)",new{id,t,p,itemId,sourceType,sourceId,title,description,hash,u,name},cancellationToken:ct));if(n==0)throw new InvalidOperationException("Período bloqueado ou inexistente.");return id;}
    public async Task<IReadOnlyList<ContractGlosaItem>> ListAsync(Guid t,CancellationToken ct){await using var db=await factory.OpenAsync(ct);var rows=await db.QueryAsync<GlosaDbRow>(new CommandDefinition("select id,period_id,item_id,glosa_number,reason,amount,status,opened_at,resolved_at from ged.contract_glosa where tenant_id=@t and reg_status='A' order by opened_at desc",new{t},cancellationToken:ct));return rows.Select(Glosa).ToList();}
    public async Task<Guid>CreateAsync(ContractGlosaCreateCommand c,CancellationToken ct){if(string.IsNullOrWhiteSpace(c.Reason)||c.Amount<0)throw new ArgumentException("Motivo obrigatório e valor não negativo.");await using var db=await factory.OpenAsync(ct);var limit=await db.ExecuteScalarAsync<decimal?>(new CommandDefinition("select case when @ItemId is null then gross_amount else (select gross_amount from ged.contract_measurement_item where tenant_id=@TenantId and period_id=@PeriodId and id=@ItemId) end from ged.contract_measurement_period where tenant_id=@TenantId and id=@PeriodId and status not in('APPROVED','CLOSED')",c,cancellationToken:ct))??throw new InvalidOperationException("Período ou item inválido.");if(c.Amount>limit)throw new ArgumentException("Glosa não pode exceder o valor bruto.");var id=Guid.NewGuid();var number=$"GL-{DateTime.UtcNow:yyyyMMdd}-{id.ToString("N")[..6].ToUpperInvariant()}";await db.ExecuteAsync(new CommandDefinition(@"insert into ged.contract_glosa(id,tenant_id,period_id,item_id,glosa_number,reason,amount,opened_by) values(@id,@TenantId,@PeriodId,@ItemId,@number,@Reason,@Amount,@UserId);insert into ged.contract_acceptance_event(tenant_id,period_id,event_type,title,description,performed_by) values(@TenantId,@PeriodId,'CONTRACT_GLOSA_CREATED','Glosa registrada',@Reason,@UserId)",new{id,c.TenantId,c.PeriodId,c.ItemId,number,c.Reason,c.Amount,c.UserId},cancellationToken:ct));await Recalculate(c.TenantId,c.PeriodId,ct);return id;}
    public async Task ResolveAsync(Guid t,Guid id,Guid u,string notes,CancellationToken ct){if(string.IsNullOrWhiteSpace(notes))throw new ArgumentException("Observação obrigatória.");await using var db=await factory.OpenAsync(ct);var p=await db.ExecuteScalarAsync<Guid?>(new CommandDefinition("update ged.contract_glosa g set status='RESOLVED',resolved_by=@u,resolved_at=now(),resolution_notes=@notes from ged.contract_measurement_period p where g.tenant_id=@t and g.id=@id and p.id=g.period_id and p.status not in('APPROVED','CLOSED') returning g.period_id",new{t,id,u,notes},cancellationToken:ct))??throw new InvalidOperationException("Glosa não encontrada ou bloqueada.");await db.ExecuteAsync(new CommandDefinition("insert into ged.contract_acceptance_event(tenant_id,period_id,event_type,title,description,performed_by) values(@t,@p,'CONTRACT_GLOSA_RESOLVED','Glosa resolvida',@notes,@u)",new{t,p,u,notes},cancellationToken:ct));await Recalculate(t,p,ct);}
    public async Task<byte[]> ExportAsync(Guid t,string type,CancellationToken ct){var allowed=new[]{"productivity-by-service","productivity-by-user","monthly-measurement","glosas-by-period","gross-vs-net","services-without-evidence","pending-acceptances"};if(!allowed.Contains(type,StringComparer.OrdinalIgnoreCase))throw new ArgumentException("Tipo de relatório inválido.");await using var db=await factory.OpenAsync(ct);string sql=type switch{"productivity-by-user"=>"select coalesce(performed_by_name,'Não informado') item,sum(quantity) quantity,sum(total_value) value from ged.contract_productivity_entry where tenant_id=@t and reg_status='A' group by performed_by_name","glosas-by-period"=>"select period_id::text item,count(*) quantity,sum(amount) value from ged.contract_glosa where tenant_id=@t and reg_status='A' group by period_id","pending-acceptances"=>"select period_code item,1::numeric quantity,net_amount value from ged.contract_measurement_period where tenant_id=@t and status='SUBMITTED' and reg_status='A'","gross-vs-net"=>"select period_code item,gross_amount quantity,net_amount value from ged.contract_measurement_period where tenant_id=@t and reg_status='A'","monthly-measurement"=>"select period_code item,count(*)::numeric quantity,net_amount value from ged.contract_measurement_period where tenant_id=@t and reg_status='A' group by period_code,net_amount","services-without-evidence"=>"select description item,quantity,gross_amount value from ged.contract_measurement_item i where tenant_id=@t and reg_status='A' and not exists(select 1 from ged.contract_measurement_evidence e where e.item_id=i.id and e.reg_status='A')",_=>"select s.description item,sum(e.quantity) quantity,sum(e.total_value) value from ged.contract_productivity_entry e join ged.contract_service_catalog s on s.id=e.service_id where e.tenant_id=@t and e.reg_status='A' group by s.description"};var rows=await db.QueryAsync<ReportDbRow>(new CommandDefinition(sql,new{t},cancellationToken:ct));var b=new StringBuilder("Item;Quantidade;Valor\r\n");foreach(var x in rows)b.Append('"').Append(x.Item.Replace("\"","\"\"")).Append("\";").Append(x.Quantity.ToString(CultureInfo.InvariantCulture)).Append(';').AppendLine(x.Value.ToString("0.00",CultureInfo.InvariantCulture));return Encoding.UTF8.GetPreamble().Concat(Encoding.UTF8.GetBytes(b.ToString())).ToArray();}
    async Task Transition(Guid t,Guid p,Guid u,string status,string eventType,string title,string?notes,string guard,CancellationToken ct){await using var db=await factory.OpenAsync(ct);var n=await db.ExecuteAsync(new CommandDefinition($@"with changed as(update ged.contract_measurement_period set status=@status,submitted_by=case when @status='SUBMITTED' then @u else submitted_by end,submitted_at=case when @status='SUBMITTED' then now() else submitted_at end,approved_by=case when @status='APPROVED' then @u else approved_by end,approved_at=case when @status='APPROVED' then now() else approved_at end,rejected_by=case when @status='REJECTED' then @u else rejected_by end,rejected_at=case when @status='REJECTED' then now() else rejected_at end,rejection_reason=case when @status='REJECTED' then @notes else rejection_reason end,closed_by=case when @status='CLOSED' then @u else closed_by end,closed_at=case when @status='CLOSED' then now() else closed_at end where tenant_id=@t and id=@p and reg_status='A' and {guard} returning 1) insert into ged.contract_acceptance_event(tenant_id,period_id,event_type,title,description,performed_by) select @t,@p,@eventType,@title,@notes,@u from changed",new{t,p,u,status,eventType,title,notes},cancellationToken:ct));if(n==0)throw new InvalidOperationException("Transição inválida ou período sem itens.");}
    async Task Recalculate(Guid t,Guid p,CancellationToken ct){await using var db=await factory.OpenAsync(ct);await db.ExecuteAsync(new CommandDefinition(@"update ged.contract_measurement_item i set glosa_amount=x.amount,net_amount=greatest(i.gross_amount-x.amount,0) from(select item_id,coalesce(sum(amount) filter(where status='OPEN'),0) amount from ged.contract_glosa where tenant_id=@t and period_id=@p and reg_status='A' group by item_id)x where i.tenant_id=@t and i.period_id=@p and i.id=x.item_id;update ged.contract_measurement_period mp set glosa_amount=x.glosa,net_amount=greatest(mp.gross_amount-x.glosa,0) from(select coalesce(sum(amount) filter(where status='OPEN'),0) glosa from ged.contract_glosa where tenant_id=@t and period_id=@p and reg_status='A')x where mp.tenant_id=@t and mp.id=@p",new{t,p},cancellationToken:ct));}
    static async Task<bool> Belongs(System.Data.Common.DbConnection db,string table,string key,Guid id,Guid t,CancellationToken ct)=>await db.ExecuteScalarAsync<bool>(new CommandDefinition($"select exists(select 1 from {table} where {key}=@id and tenant_id=@t and reg_status='A')",new{id,t},cancellationToken:ct));
    static void Mutable(string? s){if(s is null)throw new KeyNotFoundException();if(s is "APPROVED" or "CLOSED" or "SUBMITTED")throw new InvalidOperationException("Período bloqueado para alteração.");}
    static DateTimeOffset Offset(DateTime x)=>new(DateTime.SpecifyKind(x,DateTimeKind.Utc)); static ContractMeasurementPeriodItem Period(PeriodDbRow x)=>new(x.Id,x.PeriodCode,x.ReferenceMonth,x.ReferenceYear,x.Status,x.GrossAmount,x.GlosaAmount,x.NetAmount,Offset(x.OpenedAt),x.ClosedAt is null?null:Offset(x.ClosedAt.Value)); static ContractMeasurementItem Item(ItemDbRow x)=>new(x.Id,x.ServiceId,x.Description,x.Nature,x.UnitValue,x.Quantity,x.GrossAmount,x.GlosaAmount,x.NetAmount,x.Status);static ContractEvidenceItem Evidence(EvidenceDbRow x)=>new(x.Id,x.ItemId,x.SourceType,x.Title,x.Description,x.EvidenceHash,x.RegisteredByName,Offset(x.RegisteredAt));static ContractGlosaItem Glosa(GlosaDbRow x)=>new(x.Id,x.PeriodId,x.ItemId,x.GlosaNumber,x.Reason,x.Amount,x.Status,Offset(x.OpenedAt),x.ResolvedAt is null?null:Offset(x.ResolvedAt.Value));
    sealed class DashboardDbRow{public string CurrentPeriod{get;set;}="";public decimal GrossAmount{get;set;}public decimal GlosaAmount{get;set;}public decimal NetAmount{get;set;}public int PendingEntries{get;set;}public int MeasuredItems{get;set;}public int PendingAcceptances{get;set;}}
    sealed class ServiceDbRow{public Guid Id{get;set;}public string ServiceCode{get;set;}="";public string Description{get;set;}="";public string Nature{get;set;}="";public string UnitName{get;set;}="";public decimal UnitValue{get;set;}public bool Active{get;set;}}
    sealed class ProductivityDbRow{public Guid Id{get;set;}public Guid ServiceId{get;set;}public string Service{get;set;}="";public string?SourceType{get;set;}public decimal Quantity{get;set;}public decimal UnitValue{get;set;}public decimal TotalValue{get;set;}public string?PerformedByName{get;set;}public DateTime PerformedAt{get;set;}public string Status{get;set;}="";}
    sealed class PeriodDbRow{public Guid Id{get;set;}public string PeriodCode{get;set;}="";public int ReferenceMonth{get;set;}public int ReferenceYear{get;set;}public string Status{get;set;}="";public decimal GrossAmount{get;set;}public decimal GlosaAmount{get;set;}public decimal NetAmount{get;set;}public DateTime OpenedAt{get;set;}public DateTime?ClosedAt{get;set;}}
    sealed class ItemDbRow{public Guid Id{get;set;}public Guid ServiceId{get;set;}public string Description{get;set;}="";public string Nature{get;set;}="";public decimal UnitValue{get;set;}public decimal Quantity{get;set;}public decimal GrossAmount{get;set;}public decimal GlosaAmount{get;set;}public decimal NetAmount{get;set;}public string Status{get;set;}="";}
    sealed class EvidenceDbRow{public Guid Id{get;set;}public Guid?ItemId{get;set;}public string?SourceType{get;set;}public string Title{get;set;}="";public string?Description{get;set;}public string?EvidenceHash{get;set;}public string?RegisteredByName{get;set;}public DateTime RegisteredAt{get;set;}}
    sealed class GlosaDbRow{public Guid Id{get;set;}public Guid PeriodId{get;set;}public Guid?ItemId{get;set;}public string GlosaNumber{get;set;}="";public string Reason{get;set;}="";public decimal Amount{get;set;}public string Status{get;set;}="";public DateTime OpenedAt{get;set;}public DateTime?ResolvedAt{get;set;}}
    sealed class EventDbRow{public string EventType{get;set;}="";public string Title{get;set;}="";public string?Description{get;set;}public string?PerformedByName{get;set;}public DateTime OccurredAt{get;set;}}
    sealed class ReportDbRow{public string Item{get;set;}="";public decimal Quantity{get;set;}public decimal Value{get;set;}}
}
